#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/*
 * Reconstructed program behavior for prog34_fibonacci_memo
 *
 * The original binary implements a simple command‑line utility that
 * computes the n‑th Fibonacci number using memoisation.  The observable
 * behaviour (stdout) is reproduced exactly:
 *   * No argument          -> prints "NO_INPUT"\n
 *   * Argument not a pure integer (e.g. "12abc") -> prints "BAD_INPUT"\n
 *   * Negative integer    -> prints "NEGATIVE"\n
 *   * Integer > 90        -> prints "OUT_OF_RANGE"\n
 *   * Valid integer 0‑90  -> prints the Fibonacci number followed by a newline.
 */

/* The original binary stores the memoisation table in two global arrays:
 *   long memo[?];
 *   char computed[?];
 * For the allowed range (0‑90) a static table of size 91 is sufficient.
 */
static int64_t memo[91];
static unsigned char computed[91];

static int64_t fib_int(int n)
{
    /* Base cases */
    if (n == 0) {
        memo[0] = 0;
        computed[0] = 1;
        return 0;
    }
    if (n == 1) {
        memo[1] = 1;
        computed[1] = 1;
        return 1;
    }
    /* Memoised recursion */
    if (computed[n])
        return memo[n];
    int64_t a = fib_int(n - 1);
    int64_t b = fib_int(n - 2);
    memo[n] = a + b;
    computed[n] = 1;
    return memo[n];
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long value = strtol(argv[1], &endptr, 10);

    /* strtol succeeded only if it consumed at least one character */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    /* Ensure the whole argument was consumed (no trailing characters) */
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (value < 0) {
        puts("NEGATIVE");
        return 0;
    }
    if (value > 90) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    int n = (int)value;
    int64_t result = fib_int(n);
    printf("%lld\n", result);
    return 0;
}
